import React, { useState, useEffect, useRef, useCallback } from "react";

// ── Assets ───────────────────────────────────────────────────────────────────
// NAVI_IMG: transparent PNG of just the word "Navi" (from handwriting photo).
// GUIDE_FINAL_IMG: transparent PNG of "will be your guide", fully written.
// GUIDE_REVEAL_IMG: grayscale map where each pixel's brightness encodes the
//   moment it first became ink in the source recording (rank-normalized so
//   real-world pauses don't stretch the animation) — drives the write-on.
const NAVI_W = 343, NAVI_H = 204;       // native size of NAVI_IMG
const GUIDE_W = 781, GUIDE_H = 131;   // native size of GUIDE_FINAL_IMG / GUIDE_REVEAL_IMG
const IM_W = 121, IM_H = 107;   // native size of IM_FINAL_IMG / IM_REVEAL_IMG
const IM_FINAL_IMG = "data:image/png;base64,";
const IM_REVEAL_IMG = "data:image/png;base64,";
const NAVI_HAND_FONT = "data:font/woff;base64,";  // Nick's handwriting, patched so em/en dash reuse the hyphen glyph
const NAVI_IMG = "data:image/png;base64,";
const GUIDE_FINAL_IMG = "data:image/png;base64,";
const GUIDE_REVEAL_IMG = "data:image/png;base64,";
const MORESOON      = "data:image/png;base64,";
const THANKYOU_DARK = "data:image/png;base64,";

// ── Shared mutable state (written each rAF, read cross-component) ─────────────
const naviState = { hue:48, sat:68, lightness:80, depth:0.6 };

// introPhase drives NaviIntroOverlay:
//   "idle"    – nothing visible
//   "peak"    – glow has peaked, orb should emerge
//   "settle"  – letters settling, orb hovers
//   "whoosh"  – rest phrase writing, orb whooshes right
//   "ambient" – orb handed off to NaviOrb
let introPhase = "idle";

// ── Orb + mist helpers (used by NaviIntroOverlay AND NaviOrb) ────────────────
function drawOrb(ctx, x, y, sz, h, sat, li, dep) {
  if (sz < 1) return;
  [[sz*5.5, 0.10*Math.max(dep,0.3)], [sz*2.2, 0.38], [sz, 0.95]].forEach(([r,a], i) => {
    const g = ctx.createRadialGradient(x,y,0,x,y,r);
    if (i===0) {
      g.addColorStop(0, `hsla(${h},${sat}%,${li}%,${a})`);
      g.addColorStop(1, `hsla(${h},${sat*0.4}%,${li-8}%,0)`);
    } else if (i===1) {
      g.addColorStop(0, `hsla(${h},${sat*0.7}%,${li+5}%,0.38)`);
      g.addColorStop(0.5, `hsla(${h},${sat*0.4}%,${li}%,0.14)`);
      g.addColorStop(1, `hsla(${h},${sat*0.2}%,${li-8}%,0)`);
    } else {
      g.addColorStop(0, `hsla(${h+15},${sat*0.2}%,97%,${a})`);
      g.addColorStop(0.35, `hsla(${h},${sat*0.6}%,${li+6}%,0.88)`);
      g.addColorStop(0.8, `hsla(${h},${sat*0.9}%,${li-5}%,0.65)`);
      g.addColorStop(1, `hsla(${h},${sat}%,${li-12}%,0)`);
    }
    ctx.beginPath(); ctx.arc(x,y,r,0,Math.PI*2); ctx.fillStyle=g; ctx.fill();
  });
}

function drawMistWisps(ctx, x, y, fr, h, sat, li) {
  for (let i=0; i<7; i++) {
    const ph = fr*0.016 + i*1.04;
    const mx = x + Math.sin(ph*0.8+i)*60 + Math.cos(fr*0.008+i*2.1)*28;
    const my = y + Math.cos(ph*0.55+i)*42 + Math.sin(fr*0.011+i*1.6)*18;
    const mr = 24 + Math.sin(ph+i*0.7)*16;
    const op = (0.032 + Math.sin(ph*1.2)*0.016) * (0.5 + sat/150);
    const g = ctx.createRadialGradient(mx,my,0,mx,my,mr);
    g.addColorStop(0, `hsla(${h},${sat*0.5}%,${li+12}%,${op})`);
    g.addColorStop(1, `hsla(${h},${sat*0.25}%,${li+4}%,0)`);
    ctx.beginPath(); ctx.arc(mx,my,mr,0,Math.PI*2); ctx.fillStyle=g; ctx.fill();
  }
}

// ── NaviCanvas ──────────────────────────────────────────────────────────────
// Just the word "Navi." No independent animation timeline of its own anymore —
// it stays invisible until NaviIntroOverlay's flash sequence hands off to it
// (via `revealed`), at which point it simply holds the word with a live color
// tint forever after. All the transient reveal choreography (the flash, the
// orb) lives in one place now: NaviIntroOverlay.

const NaviCanvas = React.forwardRef(function NaviCanvas({ started, revealed, onPeak }, fwdRef) {
  const cr = useRef(null);
  const imgRef = useRef(null);
  const firedRef = useRef(false);

  // Load the image once, independent of anything else.
  useEffect(() => {
    const img = new window.Image();
    img.onload = () => { imgRef.current = img; };
    img.src = NAVI_IMG;
  }, []);

  // Kick off the shared intro sequence exactly once, the moment we're told to.
  useEffect(() => {
    if (started && !firedRef.current) {
      firedRef.current = true;
      introPhase = "peak";
      onPeak && onPeak();
    }
  }, [started]);

  // Once revealed, hold the word with a continuously-live color tint.
  useEffect(() => {
    if (!revealed) return;
    let aId;
    const draw = () => {
      const c = cr.current, img = imgRef.current;
      if (c && img) {
        const ctx = c.getContext("2d");
        const W = img.width, H = img.height;
        const { hue:h, sat:s, lightness:l, depth:dep } = naviState;
        const baseA = 0.52 + dep*0.22;
        ctx.clearRect(0,0,W,H);
        ctx.drawImage(img,0,0);
        ctx.save(); ctx.globalCompositeOperation = "source-atop";
        ctx.fillStyle = `hsla(${h},${s}%,${l+8}%,${baseA})`;
        ctx.fillRect(0,0,W,H); ctx.restore();
      }
      aId = requestAnimationFrame(draw);
    };
    aId = requestAnimationFrame(draw);
    return () => cancelAnimationFrame(aId);
  }, [revealed]);

  return (
    <canvas
      ref={el => { cr.current=el; if (typeof fwdRef==="function") fwdRef(el); else if (fwdRef) fwdRef.current=el; }}
      width={NAVI_W} height={NAVI_H}
      style={{ height:36, width:"auto", display:"block", overflow:"visible", opacity: revealed?1:0 }}
    />
  );
});

// ── WriteCanvas ───────────────────────────────────────────────────────────────
// Renders "will be your guide" using true per-pixel reveal order derived from
// a screen recording of it actually being written — not an approximated wipe.
// GUIDE_REVEAL_IMG encodes, per pixel, the rank-normalized moment it first
// became ink; at playback we reveal each pixel exactly when that map says to,
// with a small feather band so the edge isn't a hard on/off cut.
//
// Images are decoded as soon as this mounts (during Navi's glow/settle),
// not gated behind `started` — so when the moment to write finally arrives,
// there's no load/decode lag adding to the pause; only the deliberate one.

const WriteCanvas = React.forwardRef(function WriteCanvas({ started, durationMs=1150, onDone, finalSrc, revealSrc, nativeW, nativeH, displayHeight, translateY=0 }, fwdRef) {
  const cr = useRef(null);
  const dataRef = useRef(null);
  const startedRef = useRef(false);
  const aIdRef = useRef(null);
  const wantStartRef = useRef(false);

  const runAnimation = () => {
    if (startedRef.current) return;
    const c = cr.current, d = dataRef.current;
    if (!c || !d) return;
    startedRef.current = true;
    const { W, H, finalData, mapData } = d;
    const ctx = c.getContext("2d");
    const out = ctx.createImageData(W,H);
    const fD = finalData.data, mD = mapData.data, oD = out.data;
    const n = W*H;
    const FEATHER = 0.045;
    const t0 = performance.now();
    let doneFired = false;

    const frame = (now) => {
      const t = Math.min((now-t0)/durationMs, 1);
      for (let i=0;i<n;i++){
        const j = i*4;
        const a = fD[j+3];
        if (a===0) { oD[j+3]=0; continue; }
        const revealT = (mD[j]/255) * (1-FEATHER);
        let vis;
        if (t >= revealT+FEATHER) vis=1;
        else if (t <= revealT-FEATHER) vis=0;
        else vis=(t-(revealT-FEATHER))/(FEATHER*2);
        oD[j]=fD[j]; oD[j+1]=fD[j+1]; oD[j+2]=fD[j+2]; oD[j+3]=(a*vis)|0;
      }
      ctx.putImageData(out,0,0);
      if (t<1) { aIdRef.current = requestAnimationFrame(frame); }
      else if (!doneFired) { doneFired = true; onDone && onDone(); }
    };
    aIdRef.current = requestAnimationFrame(frame);
  };

  // Load + decode once on mount, regardless of `started`.
  useEffect(() => {
    let cancelled = false;
    const finalImg = new window.Image();
    const mapImg = new window.Image();
    let loaded = 0;

    const onBothLoaded = () => {
      if (cancelled) return;
      const c = cr.current; if (!c) return;
      const W = finalImg.width, H = finalImg.height;
      c.width = W; c.height = H;

      const off = document.createElement("canvas");
      off.width = W; off.height = H;
      const octx = off.getContext("2d");
      octx.drawImage(finalImg,0,0);
      const finalData = octx.getImageData(0,0,W,H);
      octx.clearRect(0,0,W,H);
      octx.drawImage(mapImg,0,0);
      const mapData = octx.getImageData(0,0,W,H);

      dataRef.current = { W, H, finalData, mapData };
      if (wantStartRef.current) runAnimation();
    };

    finalImg.onload = () => { loaded++; if(loaded===2) onBothLoaded(); };
    mapImg.onload   = () => { loaded++; if(loaded===2) onBothLoaded(); };
    finalImg.src = finalSrc;
    mapImg.src   = revealSrc;

    return () => { cancelled = true; if (aIdRef.current) cancelAnimationFrame(aIdRef.current); };
  }, [finalSrc, revealSrc]);

  // Fires when the parent says "go" — runs immediately if the images are
  // already decoded (the normal case), or as soon as they finish otherwise.
  useEffect(() => {
    if (started) { wantStartRef.current = true; runAnimation(); }
  }, [started]);

  return (
    <canvas
      ref={el => { cr.current=el; if (typeof fwdRef==="function") fwdRef(el); else if (fwdRef) fwdRef.current=el; }}
      width={nativeW} height={nativeH}
      style={{ height:displayHeight, width:"auto", display:"block", overflow:"visible", transform:`translateY(${translateY}px)` }}
    />
  );
});

// ── NaviIntroOverlay ──────────────────────────────────────────────────────────
// Fixed full-screen canvas. Watches introPhase.
// "peak"   → orb flashes into being at the Navi word's position/size, and that
//            same flash is what reveals the word (drawn right here, tinted,
//            in lockstep) — one event, not an orb arriving at a separately
//            self-animating word.
// "whoosh" → orb accelerates right, then hands off to NaviOrb via _naviEnter

const FLASH_FRAMES = 16;  // quick pop-into-size + word reveal (~0.27s @60fps)
const HOVER_FRAMES = 34;  // settled hover before departing (~0.57s @60fps)
const ORB_SZ = 28;

function easeOutBack(x) {
  const c1 = 1.70158, c3 = c1 + 1;
  return 1 + c3*Math.pow(x-1,3) + c1*Math.pow(x-1,2);
}

function NaviIntroOverlay({ phraseRef }) {
  const cr = useRef(null);
  useEffect(() => {
    const canvas = cr.current; if (!canvas) return;
    const ctx = canvas.getContext("2d");
    let W = window.innerWidth, H = window.innerHeight;
    canvas.width=W; canvas.height=H;
    const onR = () => { W=window.innerWidth; H=window.innerHeight; canvas.width=W; canvas.height=H; };
    window.addEventListener("resize", onR);

    // Navi word image, loaded independently here so the overlay can draw it
    // itself during the flash (this canvas and NaviCanvas are two elements,
    // but during the flash only this one is doing any drawing of the word).
    const naviImg = new window.Image();
    let naviImgReady = false;
    naviImg.onload = () => { naviImgReady = true; };
    naviImg.src = NAVI_IMG;
    const naviBuf = document.createElement("canvas");
    naviBuf.width = NAVI_W; naviBuf.height = NAVI_H;
    const naviBufCtx = naviBuf.getContext("2d");

    const o = { x:0, y:0, sz:0, hBX:0, hBY:0, hF:0, vx:0, vy:0, phase:"waiting", flashFrame:0, hoverFrame:0, rect:null };
    let fr=0, aId;
    let revealedFired = false, departFired = false;

    const draw = () => {
      fr++; ctx.clearRect(0,0,W,H);
      const { hue:h, sat:s, lightness:l, depth:dep } = naviState;

      if (introPhase==="peak" && o.phase==="waiting") {
        if (phraseRef && phraseRef.current) {
          const r = phraseRef.current.getBoundingClientRect();
          o.rect = r;
          o.x  = r.left + r.width * 0.5;
          o.y  = r.top  + r.height * 0.5;
          o.hBX = r.left + r.width * 0.12;
          o.hBY = r.bottom + 14;
        }
        o.sz=0; o.flashFrame=0; o.phase="flashing";
      }

      if (o.phase==="waiting") { aId=requestAnimationFrame(draw); return; }

      if (o.phase==="flashing") {
        o.flashFrame++;
        const t = Math.min(o.flashFrame/FLASH_FRAMES, 1);

        // Orb pops to size with a slight overshoot, then settles — a flash
        // into being, not a slow grow.
        const growT = Math.min(t/0.55, 1);
        o.sz = ORB_SZ * Math.max(0, easeOutBack(growT));

        // Word alpha ramps in slightly ahead of the orb settling, so it
        // reads as revealed BY the flash rather than arriving after it.
        const wordA = Math.min(t*1.4, 1);
        // The bright flash itself decays across the whole window.
        const flashBright = Math.max(0, 1 - Math.pow(t, 0.7));
        // Fade this extra ambient wash out well before the flash ends, so
        // its absence in hovering (which relies on drawOrb's own halo
        // instead) is never noticeable.
        const washA = Math.max(0, 1 - t/0.7);

        if (washA>0.01) {
          const mg = ctx.createRadialGradient(o.x,o.y,0,o.x,o.y,Math.max(o.sz*3.4,1));
          mg.addColorStop(0,`hsla(${h},${s*0.7}%,${l+5}%,${0.4*washA})`);
          mg.addColorStop(1,`hsla(${h},${s*0.3}%,${l}%,0)`);
          ctx.beginPath();ctx.arc(o.x,o.y,Math.max(o.sz*3.4,1),0,Math.PI*2);ctx.fillStyle=mg;ctx.fill();
        }

        // The word, tinted to match, drawn at the same spot it'll live once
        // NaviCanvas takes over — same position, same size, no seam.
        if (naviImgReady && o.rect && wordA>0) {
          const baseA = 0.52 + dep*0.22;
          naviBufCtx.clearRect(0,0,NAVI_W,NAVI_H);
          naviBufCtx.drawImage(naviImg,0,0);
          naviBufCtx.save(); naviBufCtx.globalCompositeOperation="source-atop";
          naviBufCtx.fillStyle = `hsla(${h},${s}%,${l+8}%,${baseA})`;
          naviBufCtx.fillRect(0,0,NAVI_W,NAVI_H); naviBufCtx.restore();
          ctx.save(); ctx.globalAlpha = wordA;
          ctx.drawImage(naviBuf,0,0,NAVI_W,NAVI_H, o.rect.left,o.rect.top,o.rect.width,o.rect.height);
          ctx.restore();
        }

        // Same orb halo used for hover/whoosh — scales naturally with o.sz
        // as it ramps up, so there's no rendering-style handoff later.
        drawOrb(ctx,o.x,o.y,o.sz,h,s,l,Math.max(dep,0.5));

        // The flash burst itself, layered on top, fading out — this is
        // what makes the word feel like it's revealed BY the light rather
        // than glowing on its own.
        if (flashBright>0.01) {
          ctx.save(); ctx.globalCompositeOperation="lighter";
          const fg = ctx.createRadialGradient(o.x,o.y,0,o.x,o.y,Math.max(o.sz*2.6,1));
          fg.addColorStop(0,`hsla(${h+10},${s*0.15}%,98%,${0.85*flashBright})`);
          fg.addColorStop(1,`hsla(${h},${s*0.3}%,${l+10}%,0)`);
          ctx.beginPath();ctx.arc(o.x,o.y,Math.max(o.sz*2.6,1),0,Math.PI*2);ctx.fillStyle=fg;ctx.fill();
          ctx.restore();
        }

        if (t>=1) {
          if (!revealedFired) { revealedFired=true; window._onNaviWordRevealed && window._onNaviWordRevealed(); }
          // Capture exactly where the flash left off, so hovering can glide
          // from here instead of snapping to the hover anchor.
          o.transitStartX = o.x; o.transitStartY = o.y;
          o.hoverFrame=0; o.phase="hovering";
        }

      } else if (o.phase==="hovering") {
        o.hF++; o.hoverFrame++;
        o.prevX=o.x; o.prevY=o.y;
        const jitterX = Math.sin(o.hF*0.07)*7 + Math.sin(o.hF*0.13)*3;
        const jitterY = Math.sin(o.hF*0.09)*5 + Math.sin(o.hF*0.18)*2.5 + Math.sin(o.hF*0.31)*1.5;
        const GLIDE_FRAMES = 20;
        if (o.hoverFrame <= GLIDE_FRAMES) {
          // Ease from the flash's resting spot to the hover anchor — a
          // deliberate, visible glide, not a snap. Jitter fades in over the
          // same window so it doesn't pop in at full amplitude mid-glide.
          const gt = o.hoverFrame/GLIDE_FRAMES;
          const ease = gt<0.5 ? 2*gt*gt : 1-Math.pow(-2*gt+2,2)/2;
          o.x = o.transitStartX + (o.hBX-o.transitStartX)*ease + jitterX*ease;
          o.y = o.transitStartY + (o.hBY-o.transitStartY)*ease + jitterY*ease;
        } else {
          o.x = o.hBX + jitterX;
          o.y = o.hBY + jitterY;
        }
        drawOrb(ctx,o.x,o.y,ORB_SZ,h,s,l,Math.max(dep,0.5));
        drawMistWisps(ctx,o.x,o.y,fr,h,s,l);

        if (o.hoverFrame>=HOVER_FRAMES && !departFired) {
          departFired = true;
          introPhase = "whoosh";
          window._onNaviDepart && window._onNaviDepart();
          o.vx = o.x-(o.prevX??o.x); o.vy = o.y-(o.prevY??o.y);
          o.tvx = 3.4+Math.random()*1.6; o.tvy = -0.5+Math.random()*0.9;
          o.phase="whooshing";
        }

      } else if (o.phase==="whooshing") {
        o.vx += (o.tvx-o.vx)*0.09;
        o.vy += (o.tvy-o.vy)*0.09 + (Math.random()-0.5)*0.06;
        o.vx *= 1.025; // keep accelerating once underway — this is the "zoom off"
        o.x+=o.vx; o.y+=o.vy;
        // Clamped both ends: stays at full size (1) until she's most of the
        // way across, only shrinking near the exit. Previously this was only
        // floored at 0, so early in the whoosh (well before 80% width) it
        // evaluated above 1 — ballooning her size right as departure began.
        const fade = Math.min(1, Math.max(0, 1-(o.x-W*0.80)/(W*0.28)));
        if (o.x > W+120) {
          o.phase="done";  // wait for introPhase==="done" to call _naviEnter
          aId=requestAnimationFrame(draw); return;
        }
        drawOrb(ctx,o.x,o.y,ORB_SZ*fade,h,s,l,dep);
        drawMistWisps(ctx,o.x,o.y,fr,h,s,l);
      }

      // Wait for writing to finish, then a brief breath before bg orb re-enters
      if (introPhase==="done" && o.phase==="done") {
        o.doneTimer = (o.doneTimer||0) + 1;
        if(o.doneTimer > 18) {  // ~0.3s breath at 60fps
          window._naviEnter && window._naviEnter();
          o.phase="handed-off";
        }
      }

      aId = requestAnimationFrame(draw);
    };
    draw();
    return () => { cancelAnimationFrame(aId); window.removeEventListener("resize",onR); };
  }, []);

  return <canvas ref={cr} style={{ position:"fixed",inset:0,width:"100%",height:"100%",pointerEvents:"none",zIndex:2 }} />;
}

// ── LandingTitle ──────────────────────────────────────────────────────────────

function LandingTitle({ phraseRef, onWriteDone }) {
  const [line1Op, setLine1Op] = useState(0);
  const [showPhrase, setShowPhrase] = useState(false);
  const [imDone, setImDone] = useState(false);
  const [naviRevealed, setNaviRevealed] = useState(false);
  const [writeStarted, setWriteStarted] = useState(false);
  const [fadeT, setFadeT] = useState(0);   // 0 = fully visible, 1 = fully faded

  // Line 1 fades in, then pause, then "I'm" starts writing
  useEffect(() => {
    let aId; const start = Date.now();
    const go = () => {
      const t = Math.min((Date.now()-start)/900, 1);
      const ease = t<0.5 ? 2*t*t : 1-Math.pow(-2*t+2,2)/2;
      setLine1Op(ease);
      if (t < 1) aId=requestAnimationFrame(go);
      else setTimeout(() => setShowPhrase(true), 850);
    };
    aId=requestAnimationFrame(go);
    return () => cancelAnimationFrame(aId);
  }, []);

  // NaviIntroOverlay lives as a separate top-level element (so its canvas can
  // draw above everything), so it signals back through these two — same
  // pattern already used elsewhere (_naviEnter, _raceToButton).
  useEffect(() => {
    window._onNaviWordRevealed = () => setNaviRevealed(true);
    window._onNaviDepart = () => setTimeout(() => setWriteStarted(true), 140);
    return () => { window._onNaviWordRevealed=null; window._onNaviDepart=null; };
  }, []);

  // Single synchronized fade: opacity AND the glow's blur+alpha all move
  // together, driven by one progress value every frame — no separate CSS
  // transitions on different properties that could desync (that mismatch,
  // not the glow itself, was the source of the earlier glitch).
  const startFade = () => {
    let aId; const start = Date.now(); const dur = 1100;
    const go = () => {
      const t = Math.min((Date.now()-start)/dur, 1);
      const ease = t<0.5 ? 2*t*t : 1-Math.pow(-2*t+2,2)/2;
      setFadeT(ease);
      if (t < 1) aId=requestAnimationFrame(go);
    };
    aId=requestAnimationFrame(go);
  };

  const shadowA = (0.18*(1-fadeT)).toFixed(3);
  const shadowBlur = (18*(1-fadeT)).toFixed(1);

  return (
    <div style={{ opacity: 1-fadeT, display:"flex", flexDirection:"column", alignItems:"center", gap:14, width:"100%", maxWidth:560 }}>
      <p style={{
        fontFamily:"system-ui,sans-serif", fontWeight:300, fontSize:17,
        letterSpacing:"0.07em", color:"rgba(232,226,212,0.82)",
        textAlign:"center", lineHeight:1.55, margin:0,
        opacity:line1Op, textShadow:`0 0 ${shadowBlur}px rgba(232,226,212,${shadowA})`, transition:"none",
      }}>
        A living map of SLO County's commons is being built
      </p>
      <div style={{ display:"flex", alignItems:"flex-end", gap:10 }}>
        <WriteCanvas
          started={showPhrase}
          durationMs={550}
          finalSrc={IM_FINAL_IMG} revealSrc={IM_REVEAL_IMG}
          nativeW={IM_W} nativeH={IM_H}
          displayHeight={27} translateY={1.2}
          onDone={() => setImDone(true)}
        />
        <NaviCanvas
          ref={phraseRef}
          started={imDone}
          revealed={naviRevealed}
        />
        <WriteCanvas
          started={writeStarted}
          durationMs={1150}
          finalSrc={GUIDE_FINAL_IMG} revealSrc={GUIDE_REVEAL_IMG}
          nativeW={GUIDE_W} nativeH={GUIDE_H}
          displayHeight={33} translateY={7.7}
          onDone={() => {
            introPhase="done"; onWriteDone && onWriteDone();
            // Hold so the finished phrase is actually readable, then fade —
            // independent of exactly where she is in her exit flight.
            setTimeout(() => startFade(), 900);
          }}
        />
      </div>
    </div>
  );
}

function NaviOrb({ onExploded }) {
  const canvasRef = useRef(null);
  useEffect(()=>{
    const canvas = canvasRef.current;
    if(!canvas) return;
    const ctx = canvas.getContext("2d");
    let W=window.innerWidth, H=window.innerHeight;
    canvas.width=W; canvas.height=H;
    const onResize=()=>{W=window.innerWidth;H=window.innerHeight;canvas.width=W;canvas.height=H;};
    window.addEventListener("resize",onResize);

    const palette=[
      {hue:48,  sat:68, light:80, weight:34},
      {hue:168, sat:72, light:72, weight:26},
      {hue:200, sat:66, light:70, weight:22},
      {hue:270, sat:58, light:76, weight:14},
      {hue:0,   sat:0,  light:95, weight:4 },
    ];

    const s={
      x:W*1.15,y:H*0.45,vx:-0.6,vy:0.1,
      depth:0.6,depthV:0.0004,
      hue:48,sat:68,light:80,
      tHue:48,tSat:68,tLight:80,
      phaseTimer:0,phaseDuration:180+Math.random()*260,
      trail:[],tx:W*0.5,ty:H*0.4,retargetTimer:0,
      racing:false,raceTarget:null,raceCallback:null,
      scale:1,exploding:false,explodeTimer:0,
      offscreen:true,
    };

    // Mist center wanders autonomously — never snaps to orb position
    let mistCX=W*0.5, mistCY=H*0.45;
    let mistVX=(Math.random()-0.5)*0.3, mistVY=(Math.random()-0.5)*0.15;

    const mist=Array.from({length:24},()=>({
      x:Math.random()*W,y:Math.random()*H,r:40+Math.random()*80,
      maxOpacity:0.03+Math.random()*0.05,life:0,
      maxLife:80+Math.random()*120,phase:Math.random()*Math.PI*2,
    }));

    const pickPhase=()=>{
      const tot=palette.reduce((a,p)=>a+p.weight,0);
      let r=Math.random()*tot;
      for(const p of palette){r-=p.weight;if(r<=0)return p;}
      return palette[0];
    };

    window._raceToButton=(bx,by,cb)=>{
      s.racing=true;s.raceTarget={x:bx,y:by};s.raceCallback=cb;s.scale=1;
    };
    window._naviEnter=()=>{
      s.offscreen=false;
      // Depth alone bottoms out around baseSize≈30 (its floor), which is
      // close to her hover size but far larger than how small she'd faded
      // to right before vanishing offscreen. Start scale low too so her
      // re-entry size actually matches that tapered-down departure look;
      // the existing scale-ease (below, ~5%/frame while not racing) brings
      // her back to full size naturally over about a second.
      s.depth=0.2; s.depthV=0.0004;
      s.scale=0.38;
      s.x=W*1.05; s.y=H*(0.35+Math.random()*0.3);
      s.vx=-1.2; s.vy=(Math.random()-0.5)*0.4;
      s.tx=W*0.72; s.ty=H*(0.3+Math.random()*0.4);
      s.retargetTimer=180;
      if(window._onNaviEnter) window._onNaviEnter();
    };

    let frame=0,animId;
    const retarget=()=>{
      const m=0.1;
      s.tx=W*(m+Math.random()*(1-m*2));
      s.ty=H*(m+Math.random()*(1-m*2));
      s.retargetTimer=280+Math.random()*420;
    };
    retarget();

    const draw=()=>{
      frame++;ctx.clearRect(0,0,W,H);
      // Always read current color from naviState (mist needs these before movement)
      let h=s.hue,sat=s.sat,light=s.light;
      // Mist center wanders slowly — same behavior whether orb is hidden or not
      mistVX+=(Math.random()-0.5)*0.04;
      mistVY+=(Math.random()-0.5)*0.02;
      mistVX*=0.995; mistVY*=0.995;
      // Soft boundary — nudge back toward center if drifting too far
      if(mistCX<W*0.25) mistVX+=0.08;
      if(mistCX>W*0.75) mistVX-=0.08;
      if(mistCY<H*0.2)  mistVY+=0.06;
      if(mistCY>H*0.8)  mistVY-=0.06;
      mistCX+=mistVX; mistCY+=mistVY;

      if(s.exploding){
        s.explodeTimer++;
        const ep=Math.min(s.explodeTimer/35,1);
        ctx.fillStyle=`rgba(255,252,242,${ep})`;
        ctx.fillRect(0,0,W,H);
        if(ep>=1){
          s.exploding=false;s.racing=false;s.scale=1;
          s.x=W*0.5;s.y=H*0.38;s.vx=0.1;s.vy=0.05;
          retarget();
          onExploded&&onExploded();
        }
        animId=requestAnimationFrame(draw);return;
      }

            mist.forEach(p=>{
        p.life++;
        if(p.life>p.maxLife){
          const near=Math.random()<0.35;
          p.x=near?mistCX+(Math.random()-0.5)*220:Math.random()*W;
          p.y=near?mistCY+(Math.random()-0.5)*220:Math.random()*H;
          p.r=35+Math.random()*90;p.maxOpacity=0.02+Math.random()*0.04;
          p.life=0;p.maxLife=80+Math.random()*140;p.phase=Math.random()*Math.PI*2;
        }
        const t=p.life/p.maxLife;
        const env=t<0.2?t/0.2:t>0.8?(1-t)/0.2:1;
        const mdist=Math.sqrt((p.x-mistCX)**2+(p.y-mistCY)**2);
        const lit=Math.max(0,1-mdist/300)*0.07;
        const op=(p.maxOpacity+lit)*env*(0.7+0.3*Math.sin(frame*0.04+p.phase));
        const g=ctx.createRadialGradient(p.x,p.y,0,p.x,p.y,p.r);
        g.addColorStop(0,`hsla(${h},${sat*0.7}%,${light+5}%,${op})`);
        g.addColorStop(1,`hsla(${h},${sat*0.4}%,${light-5}%,0)`);
        ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
      });
      s.phaseTimer++;
      if(s.phaseTimer>=s.phaseDuration){
        const p=pickPhase();
        s.tHue=p.hue;s.tSat=p.sat;s.tLight=p.light;
        s.phaseTimer=0;s.phaseDuration=140+Math.random()*240;
      }
      let dh=s.tHue-s.hue;
      if(dh>180)dh-=360;if(dh<-180)dh+=360;
      s.hue+=dh*0.008;s.sat+=(s.tSat-s.sat)*0.008;s.light+=(s.tLight-s.light)*0.008;
      h=s.hue;sat=s.sat;light=s.light;
      naviState.hue=h;naviState.sat=sat;naviState.lightness=light;naviState.depth=s.depth;
      // While offscreen, keep orb far right so it's not visible
      // Once _naviEnter fires, normal movement pulls her onscreen naturally
      if(s.offscreen){
        s.x=W*1.15; s.y=H*0.45;
        s.vx=0; s.vy=0;
      }
if(s.racing&&s.raceTarget){
        const rt=s.raceTarget;
        const rdx=rt.x-s.x,rdy=rt.y-s.y;
        const rdist=Math.sqrt(rdx*rdx+rdy*rdy);
        if(rdist<20){
          s.exploding=true;s.explodeTimer=0;
          s.raceTarget=null;
          if(s.raceCallback){s.raceCallback();s.raceCallback=null;}
        }else{
          // Close a fixed fraction of whatever distance remains, each frame —
          // this converges fast (a few frames) no matter how far the orb
          // happens to be from the button, so it never reads as "waiting."
          const pull=0.26;
          s.vx=rdx*pull;
          s.vy=rdy*pull;
          s.scale=1+(1-Math.min(rdist/300,1))*2.2;
        }
      }else if(!s.racing){
        s.retargetTimer--;
        if(s.retargetTimer<=0)retarget();
        const dx=s.tx-s.x,dy=s.ty-s.y;
        s.vx+=dx*0.0006+(Math.random()-0.5)*0.08;
        s.vy+=dy*0.0006+(Math.random()-0.5)*0.08;
        s.scale+=(1-s.scale)*0.05;
      }

      const maxSpd=s.racing?9999:1.4;
      const spd=Math.sqrt(s.vx**2+s.vy**2);
      if(spd>maxSpd){s.vx=(s.vx/spd)*maxSpd;s.vy=(s.vy/spd)*maxSpd;}
      s.vx*=s.racing?0.97:0.985;s.vy*=s.racing?0.97:0.985;
      s.x+=s.vx;s.y+=s.vy;

      if(!s.racing){
        const pad=60;
        if(s.x<pad)s.vx+=0.3;if(s.x>W-pad)s.vx-=0.3;
        if(s.y<pad)s.vy+=0.3;if(s.y>H-pad)s.vy-=0.3;
      }

      s.depth+=s.depthV;
      if(s.depth>1||s.depth<0.2)s.depthV*=-1;
      // Bias toward staying small: raw depth still cycles linearly (so glow/
      // color below are untouched), but size uses a powered remap of it —
      // she now lingers small/distant for most of the cycle and only
      // briefly swells to full size, instead of spending equal time at
      // every size in between.
      const sizeNorm = Math.pow(Math.max(0,(s.depth-0.2)/0.8), 5.5);
      const sizeDepth = 0.2 + sizeNorm*0.8;
      // Ceiling is half the old max (60→30); floor is smaller too, closer to
      // her ~28px intro/flash size, so "typical" reads noticeably smaller.
      const baseSize=(16+sizeDepth*14)*s.scale;



      s.trail.push({x:s.x,y:s.y,size:baseSize,h,sat,light});
      if(s.trail.length>55)s.trail.shift();
      s.trail.forEach((pt,i)=>{
        const age=i/s.trail.length;
        const flicker=0.6+0.4*Math.sin(frame*0.07+i*0.4+pt.x*0.01);
        const opacity=age*age*(s.racing?0.38:0.2)*flicker;
        const r=pt.size*(0.5+age*1.4);
        const g=ctx.createRadialGradient(pt.x,pt.y,0,pt.x,pt.y,r);
        g.addColorStop(0,`hsla(${pt.h},${pt.sat}%,${pt.light+8}%,${opacity*0.9})`);
        g.addColorStop(0.4,`hsla(${pt.h},${pt.sat*0.8}%,${pt.light}%,${opacity*0.5})`);
        g.addColorStop(1,`hsla(${pt.h},${pt.sat*0.5}%,${pt.light-10}%,0)`);
        ctx.beginPath();ctx.arc(pt.x,pt.y,r,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
      });

      s.trail.push({x:s.x,y:s.y,size:baseSize,h,sat,light});
      if(s.trail.length>55)s.trail.shift();
      s.trail.forEach((pt,i)=>{
        const age=i/s.trail.length;
        const flicker=0.6+0.4*Math.sin(frame*0.07+i*0.4+pt.x*0.01);
        const opacity=age*age*(s.racing?0.38:0.2)*flicker;
        const r=pt.size*(0.5+age*1.4);
        const g=ctx.createRadialGradient(pt.x,pt.y,0,pt.x,pt.y,r);
        g.addColorStop(0,`hsla(${pt.h},${pt.sat}%,${pt.light+8}%,${opacity*0.9})`);
        g.addColorStop(0.4,`hsla(${pt.h},${pt.sat*0.8}%,${pt.light}%,${opacity*0.5})`);
        g.addColorStop(1,`hsla(${pt.h},${pt.sat*0.5}%,${pt.light-10}%,0)`);
        ctx.beginPath();ctx.arc(pt.x,pt.y,r,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
      });

      mist.forEach(p=>{
        p.life++;
        if(p.life>p.maxLife){
          const near=Math.random()<0.35;
          p.x=near?mistCX+(Math.random()-0.5)*220:Math.random()*W;
          p.y=near?mistCY+(Math.random()-0.5)*220:Math.random()*H;
          p.r=35+Math.random()*90;p.maxOpacity=0.02+Math.random()*0.04;
          p.life=0;p.maxLife=80+Math.random()*140;p.phase=Math.random()*Math.PI*2;
        }
        const t=p.life/p.maxLife;
        const env=t<0.2?t/0.2:t>0.8?(1-t)/0.2:1;
        const mdist=Math.sqrt((p.x-mistCX)**2+(p.y-mistCY)**2);
        const lit=Math.max(0,1-mdist/300)*0.07;
        const op=(p.maxOpacity+lit)*env*(0.7+0.3*Math.sin(frame*0.04+p.phase));
        const g=ctx.createRadialGradient(p.x,p.y,0,p.x,p.y,p.r);
        g.addColorStop(0,`hsla(${h},${sat*0.7}%,${light+5}%,${op})`);
        g.addColorStop(1,`hsla(${h},${sat*0.4}%,${light-5}%,0)`);
        ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
      });

      const x=s.x,y=s.y;
      [[baseSize*5.5,0.08],[baseSize*2.2,0.32],[baseSize,0.92]].forEach(([r,a],li)=>{
        const g=ctx.createRadialGradient(x,y,0,x,y,r);
        if(li===0){g.addColorStop(0,`hsla(${h},${sat}%,${light}%,${a*s.depth})`);g.addColorStop(1,`hsla(${h},${sat*0.5}%,${light-8}%,0)`);}
        else if(li===1){g.addColorStop(0,`hsla(${h},${sat*0.7}%,${light+5}%,${a+s.depth*0.14})`);g.addColorStop(0.5,`hsla(${h},${sat*0.5}%,${light}%,0.14)`);g.addColorStop(1,`hsla(${h},${sat*0.3}%,${light-8}%,0)`);}
        else{g.addColorStop(0,`hsla(${h},${sat*0.2}%,97%,${a+s.depth*0.08})`);g.addColorStop(0.3,`hsla(${h},${sat*0.5}%,${light+6}%,0.88)`);g.addColorStop(0.7,`hsla(${h},${sat*0.8}%,${light}%,0.72)`);g.addColorStop(1,`hsla(${h},${sat}%,${light-10}%,0)`);}
        ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
      });

      animId=requestAnimationFrame(draw);
    };
    draw();
    return()=>{cancelAnimationFrame(animId);window.removeEventListener("resize",onResize);};
  },[]);
  return <canvas ref={canvasRef} style={{position:"fixed",inset:0,width:"100%",height:"100%",pointerEvents:"none",zIndex:0}} />;
}

function ThankYouScreen({ onComplete }) {
  const [tyOp, setTyOp] = useState(0);
  const [msOp, setMsOp] = useState(0);
  const [bgOp, setBgOp] = useState(1);

  useEffect(()=>{
    const phase1Start = Date.now();
    const phase1Dur = 1600;   // thank you fades in over 1.6s
    const phase2Start = phase1Start + 800;  // more soon starts 800ms later
    const phase2Dur = 1400;   // more soon fades in over 1.4s — like a breath
    const holdStart = phase1Start + Math.max(phase1Dur, 800+phase2Dur);
    const holdDur = 3500;
    const fadeOutStart = holdStart + holdDur;
    const fadeOutDur = 1200;  // both fade together
    const bgFadeStart = fadeOutStart + fadeOutDur;
    const bgFadeDur = 1400;

    let rafId;
    const animate=()=>{
      const now=Date.now();
      const t1=Math.min(Math.max((now-phase1Start)/phase1Dur,0),1);
      const t2=Math.min(Math.max((now-phase2Start)/phase2Dur,0),1);
      const t3=Math.min(Math.max((now-fadeOutStart)/fadeOutDur,0),1);
      const t4=Math.min(Math.max((now-bgFadeStart)/bgFadeDur,0),1);

      // Ease functions
      const ease = t => t<0.5?2*t*t:1-Math.pow(-2*t+2,2)/2;

      setTyOp(ease(t1)*(1-ease(t3)));
      setMsOp(ease(t2)*(1-ease(t3)));
      setBgOp(1-ease(t4));

      if(now<bgFadeStart+bgFadeDur) rafId=requestAnimationFrame(animate);
      else onComplete();
    };
    rafId=requestAnimationFrame(animate);
    return()=>cancelAnimationFrame(rafId);
  },[]);

  // Warm depth effect: layered text shadows on system font
  const tyStyle={
    fontFamily:"system-ui,sans-serif",
    fontWeight:300,
    fontSize:17,
    letterSpacing:"0.07em",
    color:"rgba(72,56,38,0.88)",       // warm dark brown
    textAlign:"center",
    lineHeight:1.55,
    margin:0,
    opacity:tyOp,
    textShadow:`
      0 1px 0 rgba(200,180,140,0.4),
      0 2px 8px rgba(180,140,80,0.15),
      0 4px 20px rgba(160,120,60,0.08)
    `,
  };

  return(
    <div style={{
      position:"fixed",inset:0,zIndex:200,
      background:`rgba(255,252,242,${bgOp})`,
      display:"flex",flexDirection:"column",
      alignItems:"center",justifyContent:"center",
      gap:22,pointerEvents:"none",
    }}>
      {/* Thank you — system font matching landing page, warm depth */}
      <p style={tyStyle}>thank you</p>

      {/* More soon — handwriting, smaller than Navi phrase */}
      <img src={MORESOON} alt="more soon"
        style={{
          height:28,width:"auto",
          opacity:msOp,
          filter:`drop-shadow(0 1px 3px rgba(160,120,60,0.25)) drop-shadow(0 2px 12px rgba(180,140,80,0.1))`,
        }}
      />
    </div>
  );
}

// ── NaviChat ──────────────────────────────────────────────────────────────
// Replaces the old email box + tree/network forms. One exchange visible at
// a time — Navi's line, then the reply, dissolving into the next through a
// glow rather than accumulating as a scrolling chat log. Structured facts
// are still captured to Airtable in the background via api/navi-chat.js;
// this only changes what's shown, not what's remembered.

const sleep = ms => new Promise(r=>setTimeout(r,ms));

// Detects URLs and email addresses in Navi's replies and renders them as
// real, clickable links in a distinct "standout" style (monospace, gold,
// underlined — same accent color already used for buttons elsewhere on the
// page, so gold reads as "interactive" consistently across the whole site),
// while everything else stays in her handwriting font.
const URL_RE = /(https?:\/\/[^\s]+|www\.[^\s]+)/gi;
const EMAIL_RE = /([\w.+-]+@[\w-]+\.[\w.-]+)/gi;
const LINK_RE = new RegExp(`(${URL_RE.source})|(${EMAIL_RE.source})`, "gi");

const linkStyle = {
  fontFamily:"ui-monospace,Menlo,monospace", fontStyle:"normal",
  color:"rgba(220,200,140,0.85)", textDecoration:"underline",
  textDecorationColor:"rgba(220,200,140,0.4)", textUnderlineOffset:2, textTransform:"none",
};

function linkify(text){
  const parts = text.split(LINK_RE).filter(Boolean);
  return parts.map((part,i)=>{
    if (URL_RE.test(part)) {
      URL_RE.lastIndex = 0;
      const href = part.startsWith("www.") ? `https://${part}` : part;
      return <a key={i} href={href} target="_blank" rel="noopener noreferrer" style={linkStyle}>{part}</a>;
    }
    EMAIL_RE.lastIndex = 0;
    if (EMAIL_RE.test(part)) {
      EMAIL_RE.lastIndex = 0;
      return <a key={i} href={`mailto:${part}`} style={linkStyle}>{part}</a>;
    }
    return <React.Fragment key={i}>{part}</React.Fragment>;
  });
}

function NaviChat({ active }){
  const [stage,setStage]=useState("navi");   // navi | waiting | navi-enter
  const [naviText,setNaviText]=useState("What brings you here — a place, a project, something that happened, or just curious what this is?");
  const [input,setInput]=useState("");
  const [history,setHistory]=useState([]);
  const [ended,setEnded]=useState(false);
  const [animKey,setAnimKey]=useState(0);
  const [showInput,setShowInput]=useState(false);
  const sessionIdRef=useRef(null);
  if(!sessionIdRef.current){
    sessionIdRef.current = (window.crypto&&window.crypto.randomUUID) ? window.crypto.randomUUID() : `${Date.now()}-${Math.random().toString(36).slice(2)}`;
  }

  // Input box appears a beat after the text, so there's a moment to read
  // before more of the UI shows up.
  useEffect(() => {
    if (!active) { setShowInput(false); return; }
    const t = setTimeout(() => setShowInput(true), 2000);
    return () => clearTimeout(t);
  }, [active]);

  const send=async()=>{
    const text=input.trim();
    if(!text||stage!=="navi"||ended)return;
    setInput("");
    const newHistory=[...history,{role:"user",content:text}];

    setStage("waiting"); setAnimKey(k=>k+1);

    let replyText, endedFlag=false;
    try{
      const [res] = await Promise.all([
        fetch("/api/navi-chat",{
          method:"POST",
          headers:{"Content-Type":"application/json"},
          body:JSON.stringify({sessionId:sessionIdRef.current, messages:newHistory}),
        }),
        sleep(350), // minimum time the pulse is visible, even on a fast reply
      ]);
      const data=await res.json();
      if(!res.ok||!data.reply) throw new Error(data.error||"no reply");
      replyText=data.reply; endedFlag=!!data.ended;
      setHistory([...newHistory, ...(data.newMessages||[])]);
    }catch(err){
      console.error("NaviChat error:",err);
      replyText="Something went a little quiet on my end — mind trying that again?";
      setHistory(newHistory);
    }

    setNaviText(replyText);
    setStage("navi-enter"); setAnimKey(k=>k+1);
    await sleep(550);
    setStage("navi");
    if(endedFlag) setEnded(true);
  };

  const { hue:h, sat:s, lightness:l } = naviState;
  const glow = `0 0 18px hsla(${h},${s*0.6}%,${Math.min(l+30,90)}%,0.35)`;

  return(
    <div style={{width:"100%",display:"flex",flexDirection:"column",gap:18,alignItems:"center"}}>
      <style>{`
        @font-face {
          font-family: "NaviHand";
          src: url(${NAVI_HAND_FONT}) format("woff");
          font-display: swap;
        }
        @keyframes naviMaterialize {
          0% { opacity:0; filter:blur(9px); transform:scale(1.035); }
          100% { opacity:1; filter:blur(0px); transform:scale(1); }
        }
        @keyframes naviPulseDot {
          0%,100% { opacity:0.22; transform:scale(1); }
          50% { opacity:0.6; transform:scale(1.3); }
        }
      `}</style>
      <div style={{minHeight:56,display:"flex",alignItems:"center",justifyContent:"center",textAlign:"center",width:"100%",padding:"0 6px"}}>
        {stage==="waiting" ? (
          <div key={animKey} style={{width:7,height:7,borderRadius:"50%",background:`hsla(${h},${s*0.7}%,70%,0.6)`,boxShadow:glow,animation:"naviPulseDot 1.2s ease-in-out infinite"}}/>
        ) : (
          <div key={animKey} style={{
            fontFamily:"NaviHand, system-ui, sans-serif",
            textTransform:"uppercase",
            fontSize:19, lineHeight:1.6,
            color:"rgba(232,226,212,0.85)",
            textShadow:glow,
            ...(stage==="navi-enter" ? {animation:"naviMaterialize 0.55s ease both"} : {}),
          }}>
            {linkify(naviText)}
          </div>
        )}
      </div>
      {!ended ? (
        <div style={{position:"relative",width:"100%",opacity:showInput?(stage==="navi"?1:0.3):0,transition:"opacity 0.5s ease",pointerEvents:(showInput&&stage==="navi")?"auto":"none"}}>
          <input value={input} onChange={e=>setInput(e.target.value)} onKeyDown={e=>e.key==="Enter"&&send()}
            placeholder="Reply to Navi…"
            style={{width:"100%",boxSizing:"border-box",background:"rgba(232,226,212,0.045)",border:"1px solid rgba(232,226,212,0.13)",borderRadius:24,color:"#e8e2d4",fontFamily:"system-ui,sans-serif",fontSize:13,fontWeight:300,padding:"13px 52px 13px 18px",outline:"none"}}/>
          <button onClick={send} aria-label="Send"
            style={{position:"absolute",right:5,top:"50%",transform:"translateY(-50%)",width:34,height:34,borderRadius:"50%",background:"rgba(200,180,100,0.16)",border:"1px solid rgba(200,180,100,0.28)",color:"rgba(232,226,212,0.85)",cursor:"pointer",fontSize:15,display:"flex",alignItems:"center",justifyContent:"center",padding:0}}>↑</button>
        </div>
      ) : (
        <div style={{textAlign:"center",fontSize:10,letterSpacing:"0.14em",textTransform:"uppercase",color:"rgba(232,226,212,0.22)",padding:"6px 0"}}>— end of conversation —</div>
      )}
    </div>
  );
}

export default function NaviLanding(){
  const[showThanks,setShowThanks]=useState(false);
  const[uiPhase,setUiPhase]=useState(0);

  useEffect(()=>{setUiPhase(1);},[]);
  const phraseRef=useRef(null);

  useEffect(()=>{
    window._onNaviEnter=()=>{
      const t4=setTimeout(()=>setUiPhase(4), 1400);  // Chat + footer
      return()=>{clearTimeout(t4);};
    };
    return()=>{ window._onNaviEnter=null; };
  },[]);

  const handleWriteDone=useCallback(()=>{
    // UI phase advances when _naviEnter fires (orb re-emerges), not here
  },[]);

  // ThankYouScreen (the race-to-button explosion + thank-you moment) is kept
  // available here — setShowThanks(true) triggers it — but nothing currently
  // calls it now that forms are gone. Could wire it to fire on a natural
  // conversational close if that's wanted later.

  return(
    <div style={{minHeight:"100vh",background:"#07090a",color:"#e8e2d4",fontFamily:"system-ui,sans-serif",fontWeight:300,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"space-between",padding:"0 24px",position:"relative",overflow:"hidden"}}>
      <NaviOrb onExploded={()=>{}}/>
      {uiPhase>=1&&<NaviIntroOverlay phraseRef={phraseRef}/>}
      {showThanks&&<ThankYouScreen onComplete={()=>setShowThanks(false)}/>}
      <div style={{flex:1,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",width:"100%",maxWidth:540,position:"relative",zIndex:1,gap:32,paddingTop:uiPhase<4?"8vh":0,paddingBottom:uiPhase>=4?"11vh":0}}>
        <LandingTitle phraseRef={phraseRef} onWriteDone={handleWriteDone}/>
        <div style={{width:"100%",maxWidth:400}}>
          <div style={{opacity:uiPhase>=4?1:0,transition:"opacity 0.8s ease"}}>
            <NaviChat active={uiPhase>=4}/>
          </div>
        </div>
      </div>
      <div style={{width:"100%",maxWidth:440,paddingBottom:32,display:"flex",flexDirection:"column",alignItems:"center",position:"relative",zIndex:1,opacity:uiPhase>=4?1:0,transition:"opacity 0.8s ease"}}>
        <div style={{fontSize:10,letterSpacing:"0.12em",color:"rgba(232,226,212,0.13)",textTransform:"uppercase"}}>A project by Subcanopy Planning</div>
      </div>
    </div>
  );
}
